import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四十七卦 困 澤水困 兌上坎下","description":"周易 - 第四十七卦 困 澤水困 兌上坎下","frontmatter":{"title":"第四十七卦 困 澤水困 兌上坎下","description":"周易 - 第四十七卦 困 澤水困 兌上坎下"},"headers":[],"relativePath":"classics/zhouyi/048.md","filePath":"classics/zhouyi/048.md"}'),l={name:"classics/zhouyi/048.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="困" tabindex="-1">困 <a class="header-anchor" href="#困" aria-label="Permalink to “困”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，貞，大人吉，無咎，有言不信。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>困，剛掩也。險以說，困而不失其所，亨；其唯君子乎？貞大人吉，以剛中也。有言不信，尚口乃窮也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤無水，困；君子以致命遂志。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>臀困於株木，入於幽谷，三歲不見。象 曰：入於幽谷，幽不明也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>困於酒食，朱紱方來，利用亨祀，徵兇，無咎。象曰：困於酒食，中有慶也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>困於石，據於蒺藜，入於其宮，不見其妻，兇。象曰：據於蒺藜，乘剛也。入於其宮，不見其妻，不祥也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>來徐徐，困於金車，吝，有終。象曰：來徐徐，志在下也。雖不當位，有與也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>劓刖，困於赤紱，乃徐有說，利用祭祀。象曰：劓刖，志未得也。乃徐有說，以中直也。利用祭祀，受福也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>困於葛藟，於臲卼，曰動悔。有悔，徵吉。象曰：困於葛藟，未當也。動悔，有悔吉，行也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
